import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['src/**/*.test.ts'],
    environment: 'node',
  },
});

import { describe, it, expect } from 'vitest';
import { isMsg } from './messages';

describe('isMsg', () => {
  it('accepts a well-formed ping message', () => {
    expect(isMsg({ type: 'ping' })).toBe(true);
  });

  it('rejects unknown message types', () => {
    expect(isMsg({ type: 'nope' })).toBe(false);
  });

  it('rejects values that are not objects', () => {
    expect(isMsg(null)).toBe(false);
    expect(isMsg(undefined)).toBe(false);
    expect(isMsg('ping')).toBe(false);
    expect(isMsg(42)).toBe(false);
  });

  it('rejects objects without a type field', () => {
    expect(isMsg({})).toBe(false);
    expect(isMsg({ kind: 'ping' })).toBe(false);
  });
});

// Launch (or attach to) the dedicated dev browser instance and ensure the
// unpacked extension is loaded. Idempotent — safe to run any time.
//
// Browser strategy: branded Chrome/Edge removed --load-extension in v137+ (2025),
// so we drive Chrome for Testing (CfT), which still supports side-loading and is
// Google's recommended vehicle for automation. On first run we fetch CfT into
// .browser/ via @puppeteer/browsers; set BROWSER_EXE to reuse an existing
// Chromium build (must still support --load-extension) and skip the download.
import { spawn, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import {
  Browser,
  detectBrowserPlatform,
  resolveBuildId,
  computeExecutablePath,
  install,
} from '@puppeteer/browsers';
import { CONFIG } from './config.mjs';
import { isUp, sleep, browserVersion, enableDevMode, findExtension, loadUnpacked } from './cdp.mjs';

const LAUNCH_TIMEOUT_MS = 30_000;
const POLL_MS = 500;
const BUILD_ID_CACHE = resolve(CONFIG.browserCacheDir, 'last-good-build-id');
const PROGRESS_STEP = 10; // print a line every 10% of the download

// Resolve a runnable browser executable. Prefers BROWSER_EXE, else a cached CfT
// build, fetching it once if absent. Returns { exe, label } for the summary.
async function resolveBrowserExe() {
  if (CONFIG.browserExe) {
    if (!existsSync(CONFIG.browserExe))
      throw new Error(`BROWSER_EXE points at a missing file: ${CONFIG.browserExe}`);
    return { exe: CONFIG.browserExe, label: 'custom (BROWSER_EXE)' };
  }

  const platform = detectBrowserPlatform();
  if (!platform) throw new Error('Could not detect the OS platform for Chrome for Testing.');

  mkdirSync(CONFIG.browserCacheDir, { recursive: true });

  // resolveBuildId hits the network; cache the answer so offline reruns still work.
  let buildId;
  try {
    buildId = await resolveBuildId(Browser.CHROME, platform, 'stable');
    writeFileSync(BUILD_ID_CACHE, buildId);
  } catch (e) {
    if (!existsSync(BUILD_ID_CACHE))
      throw new Error(`Cannot resolve a Chrome for Testing build and no cache exists`, {
        cause: e,
      });
    buildId = readFileSync(BUILD_ID_CACHE, 'utf8').trim();
    console.log(`Offline — using cached Chrome for Testing build ${buildId}.`);
  }

  const opts = { cacheDir: CONFIG.browserCacheDir, browser: Browser.CHROME, buildId };
  let exe = computeExecutablePath(opts);
  if (!existsSync(exe)) {
    console.log('Downloading Chrome for Testing (~200-300 MB, one-time)…');
    let lastPct = -PROGRESS_STEP;
    await install({
      ...opts,
      downloadProgressCallback: (downloaded, total) => {
        const pct = Math.floor((downloaded / total) * 100);
        if (pct >= lastPct + PROGRESS_STEP) {
          lastPct = pct;
          console.log(`  …${pct}%`);
        }
      },
    });
    exe = computeExecutablePath(opts);
  }
  return { exe, label: `Chrome for Testing ${buildId}` };
}

async function ensureExtension() {
  await enableDevMode();
  let ext = await findExtension();
  if (!ext) {
    console.log('Extension not loaded via --load-extension; trying CDP Extensions.loadUnpacked…');
    try {
      await loadUnpacked(CONFIG.extensionDir);
    } catch (e) {
      console.error(`Extensions.loadUnpacked failed: ${e.message}`);
    }
    ext = await findExtension();
  }
  if (!ext) {
    throw new Error(
      'Could not load the unpacked extension by any method. Branded Chrome/Edge cannot ' +
        'side-load extensions (v137+) — set BROWSER_EXE to a Chromium/Chrome-for-Testing ' +
        'build that supports --load-extension, or let this script fetch CfT automatically.',
    );
  }
  return ext;
}

let status = 'already-running';
let browserLabel = 'attached';

if (!(await isUp())) {
  status = 'launched';

  // Build dist/ if it's missing — the browser needs something to --load-extension.
  if (!existsSync(resolve(CONFIG.extensionDir, 'manifest.json'))) {
    console.log('dist/ missing — building it first…');
    const build = spawnSync(process.execPath, [resolve(CONFIG.root, 'tools/build.mjs')], {
      stdio: 'inherit',
    });
    if (build.status !== 0) throw new Error('Build failed — cannot launch without dist/.');
  }

  const { exe, label } = await resolveBrowserExe();
  browserLabel = label;

  mkdirSync(CONFIG.profileDir, { recursive: true });
  const args = [
    `--user-data-dir=${CONFIG.profileDir}`,
    `--remote-debugging-port=${CONFIG.port}`,
    '--enable-unsafe-extension-debugging',
    `--load-extension=${CONFIG.extensionDir}`,
    '--no-first-run',
    '--no-default-browser-check',
  ];
  spawn(exe, args, { detached: true, stdio: 'ignore' }).unref();

  let up = false;
  for (let waited = 0; waited < LAUNCH_TIMEOUT_MS && !up; waited += POLL_MS) {
    await sleep(POLL_MS);
    up = await isUp();
  }
  if (!up) throw new Error(`Browser did not open CDP port ${CONFIG.port} within 30s`);
}

const ext = await ensureExtension();
console.log(
  JSON.stringify(
    {
      status,
      browser: `${(await browserVersion()).Browser} (${browserLabel})`,
      cdp: `http://127.0.0.1:${CONFIG.port}`,
      extension: { id: ext.id, name: ext.name, version: ext.version, state: ext.state },
    },
    null,
    2,
  ),
);

// Zero-dependency Chrome DevTools Protocol helpers (Node 22+: global fetch & WebSocket).
// Talks to the DEV browser instance on CONFIG.port — never the user's main browser.
import { writeFileSync } from 'node:fs';
import { CONFIG } from './config.mjs';

const BASE = `http://127.0.0.1:${CONFIG.port}`;

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function browserVersion() {
  const res = await fetch(`${BASE}/json/version`);
  return res.json();
}

export async function isUp() {
  try {
    await browserVersion();
    return true;
  } catch {
    return false;
  }
}

export async function listTargets() {
  const res = await fetch(`${BASE}/json/list`);
  return res.json();
}

export class CDP {
  #ws;
  #id = 0;
  #pending = new Map();

  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve, { once: true });
      ws.addEventListener('error', () => reject(new Error(`WebSocket connect failed: ${url}`)), {
        once: true,
      });
    });
    return new CDP(ws);
  }

  constructor(ws) {
    this.#ws = ws;
    ws.addEventListener('message', (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && this.#pending.has(msg.id)) {
        const { resolve, reject } = this.#pending.get(msg.id);
        this.#pending.delete(msg.id);
        if (msg.error)
          reject(new Error(`${msg.error.message}${msg.error.data ? `: ${msg.error.data}` : ''}`));
        else resolve(msg.result);
      }
    });
  }

  send(method, params = {}) {
    const id = ++this.#id;
    const promise = new Promise((resolve, reject) => this.#pending.set(id, { resolve, reject }));
    this.#ws.send(JSON.stringify({ id, method, params }));
    return promise;
  }

  close() {
    this.#ws.close();
  }
}

export async function browser() {
  const { webSocketDebuggerUrl } = await browserVersion();
  return CDP.connect(webSocketDebuggerUrl);
}

export async function evalOnTarget(target, expression) {
  const c = await CDP.connect(target.webSocketDebuggerUrl);
  try {
    const res = await c.send('Runtime.evaluate', {
      expression,
      awaitPromise: true,
      returnByValue: true,
    });
    if (res.exceptionDetails) {
      throw new Error(
        `Evaluate failed on ${target.url}: ${res.exceptionDetails.exception?.description ?? JSON.stringify(res.exceptionDetails)}`,
      );
    }
    return res.result.value;
  } finally {
    c.close();
  }
}

// chrome://extensions has the chrome.developerPrivate API — our management surface.
export async function extensionsPage() {
  const find = async () =>
    (await listTargets()).find((t) => t.type === 'page' && t.url.startsWith('chrome://extensions'));
  let page = await find();
  if (!page) {
    const b = await browser();
    try {
      await b.send('Target.createTarget', { url: 'chrome://extensions/' });
    } finally {
      b.close();
    }
    for (let i = 0; i < 20 && !page; i++) {
      await sleep(150);
      page = await find();
    }
  }
  if (!page) throw new Error('Could not open chrome://extensions management page');
  return page;
}

export async function enableDevMode() {
  const page = await extensionsPage();
  return evalOnTarget(
    page,
    `new Promise((r) =>
    chrome.developerPrivate.updateProfileConfiguration({ inDeveloperMode: true },
      () => r(chrome.runtime.lastError?.message ?? null)))`,
  );
}

export async function extensionsInfo() {
  const page = await extensionsPage();
  return evalOnTarget(page, `new Promise((r) => chrome.developerPrivate.getExtensionsInfo(r))`);
}

// Match by unpacked path, not name — the path is what identifies our build
// (renames would otherwise strand the dev loop). Name kept as a fallback for
// robustness if developerPrivate ever omits the path.
export async function findExtension(name = CONFIG.extensionName) {
  const wanted = CONFIG.extensionDir.replaceAll('\\', '/').toLowerCase();
  const all = (await extensionsInfo()) ?? [];
  return (
    all.find((e) => (e.path ?? '').replaceAll('\\', '/').toLowerCase() === wanted) ??
    all.find((e) => e.name === name)
  );
}

// Chrome accumulates extension errors across loads; clear them so each
// reload's error report reflects only the current code.
export async function clearExtensionErrors(id) {
  const page = await extensionsPage();
  return evalOnTarget(
    page,
    `new Promise((r) =>
    chrome.developerPrivate.deleteExtensionErrors({ extensionId: ${JSON.stringify(id)} },
      () => r(chrome.runtime.lastError?.message ?? null)))`,
  );
}

// Resolves to null on success, or a LoadError-ish object on failure.
export async function reloadExtension(id) {
  const page = await extensionsPage();
  return evalOnTarget(
    page,
    `new Promise((r) =>
    chrome.developerPrivate.reload(${JSON.stringify(id)},
      { failQuietly: true, populateErrorForUnpacked: true },
      (err) => r(err ?? (chrome.runtime.lastError ? { message: chrome.runtime.lastError.message } : null))))`,
  );
}

// Initial load fallback; needs --enable-unsafe-extension-debugging on the browser.
export async function loadUnpacked(path) {
  const b = await browser();
  try {
    return await b.send('Extensions.loadUnpacked', { path });
  } finally {
    b.close();
  }
}

export async function createTab(url) {
  const b = await browser();
  let targetId;
  try {
    ({ targetId } = await b.send('Target.createTarget', { url }));
  } finally {
    b.close();
  }
  for (let i = 0; i < 20; i++) {
    const t = (await listTargets()).find((t) => t.id === targetId);
    if (t?.webSocketDebuggerUrl) {
      // Wait until the document (and, on extension pages, the chrome.* APIs)
      // is actually ready — evaluating too early hits a half-initialized context.
      for (let j = 0; j < 30; j++) {
        try {
          if (await evalOnTarget(t, `document.readyState === 'complete'`)) return t;
        } catch {
          /* target still swapping contexts */
        }
        await sleep(100);
      }
      return t;
    }
    await sleep(150);
  }
  throw new Error(`Opened ${url} but target ${targetId} never appeared in /json/list`);
}

export async function closeTab(targetId) {
  const b = await browser();
  try {
    await b.send('Target.closeTarget', { targetId });
  } finally {
    b.close();
  }
}

export async function screenshot(target, file) {
  const b = await browser();
  try {
    await b.send('Target.activateTarget', { targetId: target.id });
  } finally {
    b.close();
  }
  const c = await CDP.connect(target.webSocketDebuggerUrl);
  try {
    await c.send('Page.enable');
    const { data } = await c.send('Page.captureScreenshot', { format: 'png' });
    writeFileSync(file, Buffer.from(data, 'base64'));
    return file;
  } finally {
    c.close();
  }
}

{
  "manifest_version": 3,
  "name": "AI Extension Template",
  "version": "0.1.0",
  "description": "Replace me — scaffolded by ai-chrome-extension-template.",
  "background": {
    "service_worker": "background.js",
    "type": "module"
  },
  "action": {
    "default_popup": "popup.html",
    "default_title": "AI Extension Template"
  }
}

// MV3 background service worker — the extension's event hub.
//
// Message contract: every request shape lives in src/lib/messages.ts. To add a
// behaviour, add a variant to the Msg union there, then add a matching case to
// handle() below — the typed switch keeps the two in lockstep and TypeScript
// flags any request type you forget to handle.
//
// The { type: 'ping' } → { pong: true, version } reply is load-bearing:
// tools/smoke.mjs asserts it to prove the SW is alive. Keep it working.
import { isMsg, type Msg, type MsgResponse } from './lib/messages';

chrome.runtime.onInstalled.addListener((details) => {
  console.log(`[background] installed (${details.reason})`);
});

// Pure request→response dispatch. Add a case per new Msg variant.
function handle(message: Msg): MsgResponse[Msg['type']] {
  switch (message.type) {
    case 'ping':
      return { pong: true, version: chrome.runtime.getManifest().version };
    default:
      // Exhaustiveness guard: if a new Msg variant is unhandled, this line
      // fails to type-check, pointing you straight at the missing case.
      return assertNever(message.type);
  }
}

function assertNever(value: never): never {
  throw new Error(`Unhandled message type: ${String(value)}`);
}

chrome.runtime.onMessage.addListener((message: unknown, _sender, sendResponse) => {
  if (!isMsg(message)) return false; // not ours — let other listeners try
  sendResponse(handle(message));
  return true; // response delivered synchronously; keep the channel tidy
});

// Popup entry point. Renders the extension's name/version from the manifest and
// pings the service worker to show it's alive. Framework-free DOM code — swap in
// whatever UI you like, but keep #app populated (tools/smoke.mjs checks for it).
import { sendMessage } from '../lib/messages';

const manifest = chrome.runtime.getManifest();

function setText(id: string, text: string): void {
  const el = document.getElementById(id);
  if (el) el.textContent = text;
}

setText('name', manifest.name);
setText('version', `v${manifest.version}`);

// Ask the SW to confirm it's running, then reflect the result in the status line.
sendMessage({ type: 'ping' })
  .then((res) => {
    setText(
      'status',
      res.pong ? `Service worker: OK (v${res.version})` : 'Service worker: no reply',
    );
  })
  .catch((err: unknown) => {
    setText('status', `Service worker error: ${err instanceof Error ? err.message : String(err)}`);
  });

// Typed message protocol between the extension's pages (popup, options, content
// scripts) and the background service worker. Keeping every message shape in one
// union means the SW's handler and the UI's callers can never drift apart —
// add a new request/response pair here first, then handle it in background.ts.

// Requests: what a page can ask the service worker to do.
export type PingRequest = { type: 'ping' };

// Add more request variants to this union as the extension grows, e.g.
//   | { type: 'search'; query: string }
export type Msg = PingRequest;

// Responses, keyed by request type. Extend alongside Msg.
export type PingResponse = { pong: true; version: string };

export type MsgResponse = { ping: PingResponse };

// Runtime type guard: is this unknown value one of our messages? Used by the SW
// to reject anything it doesn't recognise, and unit-testable without chrome.*.
export function isMsg(value: unknown): value is Msg {
  if (typeof value !== 'object' || value === null) return false;
  const type = (value as { type?: unknown }).type;
  return type === 'ping';
}

// Typed wrapper so UI code gets inference on both the request and the response
// instead of the untyped chrome.runtime.sendMessage overloads.
export function sendMessage<T extends Msg>(message: T): Promise<MsgResponse[T['type']]> {
  return chrome.runtime.sendMessage(message);
}
